/**
 * Every program's commands, by number (core abi/cmd: `major << 8 | minor`), and the
 * packet each carries — an XTP branch whose children are its fields, in order. A
 * command with no fields carries no packet. The majors below PROGRAM_MAJOR are xpute's;
 * a program numbers its own from there, in a table of its own that names this one as
 * its base, so the two never give out one number twice.
 *
 * The direction is the ring: `packet` is what the host submits, `signal` what the guest
 * raises on the completion ring.
 */

import type { BranchCursor, NodeCursor } from "@xpute/core/wire/xtp/mod.ts";
import type { U8Array } from "@xpute/core/abi/array.ts";
import type { f64, u32, u64 } from "@xpute/core/abi/word.ts";
import { packet } from "@xpute/runtime/ipc/doorbell.ts";
import type { FetchFail } from "@xpute/runtime/abi/fetch.spec.ts";

/** What a command is about. */
export const enum Major {
  NOP = 0x00,
  FETCH = 0x01,
}

/** A fetch's verbs. */
export const enum FetchMinor {
  START = 0x01,
  CANCEL = 0x02,
  DONE = 0x03,
}

/** What a read came to. **Absent is an outcome, not a code the guest reads.**
 * There is no such object, however the protocol spells that — an HTTP 404, a
 * missing file — and the host is the one that can tell. */
export const enum FetchOutcome {
  Read = 0,
  Aborted = 1,
  Error = 2,
  Absent = 3,
}

/** Every program's commands. */
export const enum Command {
  /** Replies with its packet's value, or 0 where it has none — the rings' own test. */
  NOP = 0x0000,
  /** An object the guest wants read, named in the guest's terms: a source, a number the
   * program gives each place it reads from, and a name inside it. The host is the one
   * that knows what address that is and what protocol reaches it. The key is the
   * guest's, handed back and never read into. */
  FETCH_START = 0x0101,
  /** Stop this read. The host settles it as aborted. */
  FETCH_CANCEL = 0x0102,
  /** A read the host finished, its body held as `body` until the guest reads it (ipc/sys's READ). */
  FETCH_DONE = 0x0103,
}

/** A branch of records, each read by `read`. */
function list<T>(b: BranchCursor, read: (b: BranchCursor) => T): T[] {
  return Array.from({ length: b.len }, (_, k) => read(b.at_branch(k)));
}

/** A record that may be absent. */
function optional<T>(c: NodeCursor, read: (b: BranchCursor) => T): T | null {
  const present = c.opt();
  return present === undefined ? null : read(present.as_branch());
}

/** Command.NOP's packet. */
export interface Nop {
  value: u32;
}

export function encode_nop(p: Nop): U8Array {
  return packet((b) => b.u32(p.value));
}

/** Command.FETCH_START's signal. */
export interface FetchStartSignal {
  key: u64;
  source: u32;
  name: string;
}

export function read_fetch_start(b: BranchCursor): FetchStartSignal {
  return { key: b.at(0).get<u64>(), source: b.at(1).get<u32>(), name: b.at(2).get<string>() };
}

/** Command.FETCH_CANCEL's signal. */
export interface FetchCancelSignal {
  key: u64;
}

export function read_fetch_cancel(b: BranchCursor): FetchCancelSignal {
  return { key: b.at(0).get<u64>() };
}

/** Command.FETCH_DONE's packet. */
export interface FetchDone {
  key: u64;
  outcome: FetchOutcome;
  body: u32;
  /** 0 for none. */
  body_bytes: u32;
  fail: FetchFail;
  /** Whatever number the host refused with, kept for a reader to print and for nothing to branch on. */
  detail: u32;
  net_ms: f64;
}

export function encode_fetch_done(p: FetchDone): U8Array {
  return packet((b) => b.u64(p.key).u32(p.outcome).u32(p.body).u32(p.body_bytes).u32(p.fail).u32(p.detail).f64(p.net_ms));
}
